begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
-- FIXTURE_BEGIN: synthetic scoped outside history and local actors.
insert into auth.users(id,email,raw_user_meta_data) values('db490000-0000-4000-8000-000000000001','clinical-import-admin@example.test','{}'),('db490000-0000-4000-8000-000000000002','clinical-import-other@example.test','{}');
insert into user_roles(user_id,role) values('db490000-0000-4000-8000-000000000001','ADMIN'),('db490000-0000-4000-8000-000000000002','DVM');
create temp table fx(k text primary key,id uuid);create temp table data(k text primary key,v jsonb);grant all on fx,data to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db490000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from save_client(auth.uid(),null,null,'Clinical','Import','+13035550199','clinical-import@example.test','EMAIL',null,null);
insert into fx select 'pet',id from save_patient(null,(select id from fx where k='client'),null,'Scoped dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select k,gen_random_uuid() from unnest(array['mapping','mapping2','snapshot','snapshot2','legacy','terminal','run','history','other-run']) k;
reset role;
insert into ezyvet_import_snapshots(id,source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by) select id,'https://api.trial.ezyvet.com','clinical-test-site','animal',case when k='snapshot' then '77' else '88' end,jsonb_build_object('id',case when k='snapshot' then 77 else 88 end),k,'db490000-0000-4000-8000-000000000001' from fx where k in ('snapshot','snapshot2');
insert into ezyvet_record_links(id,request_id,request_hash,source_origin,source_site_uid,resource,external_id,snapshot_id,head_version,client_id,pet_id,local_version,action,reason,approved_by)
select id,gen_random_uuid(),k,'https://api.trial.ezyvet.com','clinical-test-site','animal',case when k='mapping' then '77' else '88' end,(select id from fx where k=case when m.k='mapping' then 'snapshot' else 'snapshot2' end),1,(select id from fx where k='client'),(select id from fx where k='pet'),1,'link','Synthetic approved mapping','db490000-0000-4000-8000-000000000001' from fx m where k in ('mapping','mapping2');
insert into data values('items','[{"external_id":"101","payload":{"id":101,"animal_id":77,"comments":"<script>outside prose</script>","vet_id":"outside-user","history_system":"opaque"}}]');
insert into fx select k,gen_random_uuid() from unnest(array['source-approval','extraction','linked','tombstone','second-extraction','later-source','discrepancy','release']) k;
set local role service_role;
insert into data select 'run',claim_ezyvet_clinical_import((select id from fx where k='run'),'db490000-0000-4000-8000-000000000001','clinical-test-site','history','https://api.trial.ezyvet.com',(select id from fx where k='mapping'));
select stage_ezyvet_import_page((select id from fx where k='run'),'db490000-0000-4000-8000-000000000001',(select (v->>'lease_id')::uuid from data where k='run'),1,true,(select v from data where k='items'));
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db490000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into data select 'candidate',list_ezyvet_clinical_candidates((select id from fx where k='mapping'),'history')#>'{candidates,0}';
insert into data select 'source-payload',jsonb_build_object('animal_link_id',(select id from fx where k='mapping'),'snapshot_id',v->'id','payload_hash',v->'payload_hash','observed_head_version',v->'head_version','patient_version',1,'consult_mode','not_referenced','consult_snapshot_id',null,'consult_payload_hash',null,'consult_head_version',null,'reason','PRIVATE administrator source review') from data where k='candidate';
insert into data select 'prepared-source',prepare_ezyvet_history_approval((select id from fx where k='source-approval'),(select id from fx where k='pet'),(select v from data where k='source-payload'));
insert into data select 'source-receipt',approve_ezyvet_history((select id from fx where k='source-approval'),(select id from fx where k='pet'),(select v#>>'{request,request_hash}' from data where k='prepared-source'),true);
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db490000-0000-4000-8000-000000000002","role":"authenticated"}',true);
insert into data select 'extraction-payload',jsonb_build_object('sources',jsonb_build_array(jsonb_build_object('id',v#>'{receipt,id}','version_hash',v#>'{receipt,version_hash}')),'patient_version',1,'action','create','problem_id',null,'problem_version',null,'fields',jsonb_build_object('title','Reviewed vaccine reaction','notes','DVM-authored reviewed finding','onset_date',null,'status','active','importance','high'),'duplicate_decision','distinct_finding','reason','PRIVATE DVM duplicate review') from data where k='source-receipt';
insert into data select 'prepared-extraction',prepare_ezyvet_problem_extraction((select id from fx where k='extraction'),(select id from fx where k='pet'),(select v from data where k='extraction-payload'));
insert into data select 'extraction-receipt',approve_ezyvet_problem_extraction((select id from fx where k='extraction'),(select id from fx where k='pet'),(select v#>>'{request,request_hash}' from data where k='prepared-extraction'),true);
insert into fx select 'problem',(v#>>'{receipt,problem_id}')::uuid from data where k='extraction-receipt';
-- FIXTURE_END
insert into data select 'selection',jsonb_build_object('problem_ids',jsonb_build_array((select id from fx where k='problem')));
insert into data select 'preview',preview_record_release_v6((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='selection'));
select is((select v#>>'{snapshot,schema_version}' from data where k='preview'),'6','Explicit schema6 preview');
select is((select jsonb_array_length(v#>'{snapshot,imported_histories}') from data where k='preview'),0,'Native problem selection does not force outside narrative disclosure');
select is((select v#>>'{snapshot,problem_source_extractions,0,sources,0,narrative_included}' from data where k='preview'),'false','Compact lineage discloses omitted narrative');
select is((select v#>>'{snapshot,problem_source_extractions,0,problem_fields,importance}' from data where k='preview'),'high','Native high importance frozen independently');
select throws_ok($$select confirm_record_release((select id from fx where k='release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='selection'),(select v->'snapshot' from data where k='preview'),(select v->>'source_hash' from data where k='preview'),true)$$,'42501',null,'Absent actual schema6 acceptance blocks confirmation');
reset role;
insert into record_release_policy(id,enabled,accepted_by,accepted_at,acceptance_reference,accepted_schema_version) values(true,true,'Synthetic rollback reviewer',now(),'TEST ONLY',6);
set local role authenticated;
insert into data select 'release-receipt',to_jsonb(confirm_record_release((select id from fx where k='release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='selection'),(select v->'snapshot' from data where k='preview'),(select v->>'source_hash' from data where k='preview'),true));
select is(read_record_release((select id from fx where k='release'))->>'eligible','true','Unchanged schema6 release currently eligible');
insert into data select 'history-only-selection',jsonb_build_object('imported_history_ids',jsonb_build_array((select id from fx where k='source-approval')));
insert into data select 'history-only-preview',preview_record_release_v6((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='history-only-selection'));
select is((select jsonb_array_length(v#>'{snapshot,imported_histories}') from data where k='history-only-preview'),1,'History-only release works without implicit clinical content');
select is((select jsonb_array_length(v#>'{snapshot,patient_summaries}') from data where k='history-only-preview'),0,'History-only does not silently include patient summary');
insert into fx values('history-only-release',gen_random_uuid());
select confirm_record_release((select id from fx where k='history-only-release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='history-only-selection'),(select v->'snapshot' from data where k='history-only-preview'),(select v->>'source_hash' from data where k='history-only-preview'),true);
select is(read_record_release((select id from fx where k='history-only-release'))->>'eligible','true','History-only confirmed release reads with exact hash');
select is((select count(*)::integer from jsonb_each(select_all_record_release_sources_v6((select id from fx where k='pet'))->'selection') where jsonb_typeof(value)='array'),15,'Schema6 select-all provides fifteen arrays');
select is(jsonb_array_length(list_record_release_sources_v6((select id from fx where k='pet'))->'imported_history_ids'),1,'Versioned release discovery includes approved narrative');
insert into data select 'full-selection',v||jsonb_build_object('imported_history_ids',jsonb_build_array((select id from fx where k='source-approval'))) from data where k='selection';
select is(preview_record_release_v6((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='full-selection'))#>>'{snapshot,problem_source_extractions,0,sources,0,narrative_included}','true','Explicit narrative selection matches compact source reference');
select throws_ok($$select preview_record_release_v6((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test','{}')$$,'23514',null,'Schema6 still rejects no selected content');
-- Legacy problem-only release before imported association remains frozen but becomes ineligible.
insert into fx select 'legacy-problem',id from save_patient_problem(null,(select id from fx where k='pet'),null,'Preexisting local finding','Existing local text',null,'active','routine');
insert into fx values('legacy-release',gen_random_uuid());
insert into data select 'legacy-selection',jsonb_build_object('problem_ids',jsonb_build_array((select id from fx where k='legacy-problem')));
insert into data select 'legacy-preview',preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='legacy-selection'));
select confirm_record_release((select id from fx where k='legacy-release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='legacy-selection'),(select v->'snapshot' from data where k='legacy-preview'),(select v->>'source_hash' from data where k='legacy-preview'),true);
insert into data select 'legacy-link-payload',(select v from data where k='extraction-payload')||jsonb_build_object('action','link','problem_id',p.id,'problem_version',p.version,'duplicate_decision','link_existing','fields',jsonb_build_object('title',p.title,'notes',p.notes,'onset_date',p.onset_date,'status',p.status,'importance',p.importance)) from patient_problems p where id=(select id from fx where k='legacy-problem');
insert into data select 'legacy-link-prepared',prepare_ezyvet_problem_extraction((select id from fx where k='linked'),(select id from fx where k='pet'),(select v from data where k='legacy-link-payload'));
select approve_ezyvet_problem_extraction((select id from fx where k='linked'),(select id from fx where k='pet'),(select v#>>'{request,request_hash}' from data where k='legacy-link-prepared'),true);
select is(read_record_release((select id from fx where k='legacy-release'))->>'eligible','false','New association invalidates schema5 delivery without native edit');
select is((confirm_record_release((select id from fx where k='legacy-release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='legacy-selection'),(select v->'snapshot' from data where k='legacy-preview'),(select v->>'source_hash' from data where k='legacy-preview'),true)).snapshot,(select v->'snapshot' from data where k='legacy-preview'),'Exact old UUID recovers unchanged schema5 snapshot');
select throws_ok($$select confirm_record_release(gen_random_uuid(),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='legacy-selection'),(select v->'snapshot' from data where k='legacy-preview'),(select v->>'source_hash' from data where k='legacy-preview'),true)$$,'23514',null,'Fresh legacy confirmation cannot omit imported lineage');
reset role;set local session_replication_role=replica;delete from record_release_events where release_id=(select id from fx where k='legacy-release');set local session_replication_role=origin;set local role authenticated;
select is(read_record_release((select id from fx where k='legacy-release'))->>'eligible','false','Read-time guard catches an association predating5100 event triggers');
-- A new extraction association also invalidates an already-confirmed schema6 problem package.
insert into data select 'second-link-payload',(select v from data where k='extraction-payload')||jsonb_build_object('action','link','problem_id',(select id from fx where k='problem'),'problem_version',1,'duplicate_decision','link_existing');
insert into data select 'second-link-prepared',prepare_ezyvet_problem_extraction((select id from fx where k='second-extraction'),(select id from fx where k='pet'),(select v from data where k='second-link-payload'));
select approve_ezyvet_problem_extraction((select id from fx where k='second-extraction'),(select id from fx where k='pet'),(select v#>>'{request,request_hash}' from data where k='second-link-prepared'),true);
select is(read_record_release((select id from fx where k='release'))->>'eligible','false','New source review association invalidates schema6 without native field change');
select is((select version from patient_problems where id=(select id from fx where k='problem')),1,'Provenance-only association leaves native version unchanged');
select isnt(preview_record_release_v6((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','clinical-import@example.test',(select v from data where k='selection'))->>'source_hash',(select v->>'source_hash' from data where k='preview'),'Fresh schema6 hash includes additional extraction provenance');
select * from finish();rollback;
